def power_iter(A, iters=500):
    n=A.shape[0]
    v=np.random.randn(n)+1j*np.random.randn(n)
    v/=np.linalg.norm(v)
    for _ in range(iters):
        w=A@v
        norm=np.linalg.norm(w)
        if norm==0:
            break
        v=w/norm
    Av=A@v
    lam=(v.conj()@Av)/(v.conj()@v)
    return lam,v

